export const W=900,H=1200;
export function stroke(ctx,s,from=0){const p=s.points;if(!p.length||from>=p.length)return;ctx.save();ctx.strokeStyle=s.color;ctx.fillStyle=s.color;ctx.globalAlpha=s.tool==='highlighter'?.3:1;ctx.lineCap='round';ctx.lineJoin='round';if(s.tool==='highlighter'){if(from>0){ctx.restore();return;}ctx.lineWidth=s.width*5;ctx.beginPath();ctx.moveTo(p[0][0],p[0][1]);for(const q of p.slice(1))ctx.lineTo(q[0],q[1]);if(p.length===1)ctx.lineTo(p[0][0]+.1,p[0][1]);ctx.stroke();}else{for(let i=from;i<p.length;i++){const a=p[Math.max(0,i-1)],b=p[i];ctx.lineWidth=s.width*(.35+.9*((a[2]+b[2])/2));ctx.beginPath();ctx.moveTo(a[0],a[1]);ctx.lineTo(b[0],b[1]);ctx.stroke();if(i===0){ctx.beginPath();ctx.arc(b[0],b[1],ctx.lineWidth/2,0,Math.PI*2);ctx.fill();}}}ctx.restore();}
export function renderInk(canvas,strokes){const c=canvas.getContext('2d');c.setTransform(1,0,0,1,0,0);c.clearRect(0,0,canvas.width,canvas.height);c.save();c.scale(canvas.width/W,canvas.height/H);for(const s of strokes)stroke(c,s);c.restore();}
export function paper(ctx,template){ctx.fillStyle='#101113';ctx.fillRect(0,0,W,H);ctx.strokeStyle='#242527';ctx.fillStyle='#343435';ctx.lineWidth=.6;if(template==='dots'){for(let y=32;y<H;y+=28)for(let x=32;x<W;x+=28){ctx.beginPath();ctx.arc(x,y,.8,0,Math.PI*2);ctx.fill();}}else if(template==='grid'||template==='ruled'){for(let y=32;y<H;y+=28){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke();}if(template==='grid')for(let x=32;x<W;x+=28){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,H);ctx.stroke();}}}
export function pageImage(p){const c=document.createElement('canvas');c.width=W;c.height=H;const x=c.getContext('2d');paper(x,p.template);x.fillStyle='#eee8db';x.font='24px Georgia';let y=100;for(const line of p.text.split('\n')){let current='';for(const word of line.split(' ')){if(x.measureText(current+word).width>744){x.fillText(current,78,y);y+=38;current='';}current+=word+' ';}x.fillText(current,78,y);y+=38;}for(const s of p.strokes)stroke(x,s);return c;}
export function hitStroke(s,x,y,radius=16){return s.points.some((b,i)=>{const a=s.points[Math.max(0,i-1)],dx=b[0]-a[0],dy=b[1]-a[1],t=Math.max(0,Math.min(1,((x-a[0])*dx+(y-a[1])*dy)/(dx*dx+dy*dy||1)));return Math.hypot(x-a[0]-t*dx,y-a[1]-t*dy)<radius+(s.tool==='highlighter'?s.width*2.5:s.width);});}
